package ktanesolver.module.modded.regular.sonicknuckles;import static org.assertj.core.api.Assertions.assertThat;import org.junit.jupiter.api.Test;import ktanesolver.entity.*;import ktanesolver.logic.*;import ktanesolver.module.modded.regular.sonicknuckles.SonicKnucklesInput.*;
class SonicKnucklesSolverTest{private final SonicKnucklesSolver s=new SonicKnucklesSolver();@Test void findsEachIllegalObjectAndComputesHits(){check(Sound.BUMPER,Sound.JUMP,Sound.BLUE_SPHERE,"hero");check(Sound.JUMP,Sound.BUMPER,Sound.BLUE_SPHERE,"badnik");check(Sound.JUMP,Sound.BLUE_SPHERE,Sound.BUMPER,"monitor");assertThat(SonicKnucklesSolver.hits(17,1500,14,13)).isEqualTo(1);}@Test void invertsParityAndStoresSouvenirFacts(){var m=new ModuleEntity();var x=solve(m,new SonicKnucklesInput(Zone.MUSHROOM_HILL,Sound.BUMPER,Sound.JUMP,Sound.BLUE_SPHERE,Hero.KNUCKLES,Badnik.GHOST,Monitor.RUNNING_BOOTS,1500,55));assertThat(x.firstHitParity()).isEqualTo("odd");assertThat(x.ringSecond()).isEqualTo(15);assertThat(m.getState()).containsEntry("badnik","Ghost").containsEntry("monitor","Running Boots");}@Test void rejectsAmbiguousSounds(){var r=s.solve(new RoundEntity(),new BombEntity(),new ModuleEntity(),new SonicKnucklesInput(Zone.MUSHROOM_HILL,Sound.BUMPER,Sound.SPIN,Sound.JUMP,Hero.SONIC,Badnik.CLUCKOID,Monitor.FIRE_SHIELD,1500,20));assertThat(r).isInstanceOf(SolveFailure.class);}private void check(Sound h,Sound b,Sound m,String object){assertThat(solve(new ModuleEntity(),new SonicKnucklesInput(Zone.MUSHROOM_HILL,h,b,m,Hero.SONIC,Badnik.CLUCKOID,Monitor.FIRE_SHIELD,1500,20)).object()).isEqualTo(object);}private SonicKnucklesOutput solve(ModuleEntity m,SonicKnucklesInput i){return((SolveSuccess<SonicKnucklesOutput>)s.solve(new RoundEntity(),new BombEntity(),m,i)).output();}}
